function withImg(p) { return Object.assign({}, p, {img: 'images/' + p.id + '.jpg'}); }

function matchSearch(text, g) {
  const kwSorted = KW.slice().sort((a, b) => b[0].length - a[0].length);
  return PERFUMES.map(p => {
    if (g !== 'all' && p.gender !== g && p.gender !== '中性') return {p: withImg(p), score: -1, hits: []};
    let score = 0; const hits = []; const usedTags = {};
    kwSorted.forEach(([w, tag]) => {
      if (text.includes(w) && !usedTags[tag] && p.tags.includes(tag)) { usedTags[tag] = true; score += 2; if (!hits.includes(w)) hits.push(w); }
    });
    NOTE_WORDS.forEach(nw => {
      if (text.includes(nw) && (p.top + p.heart + p.base).includes(nw)) { score += 1; if (!hits.includes(nw)) hits.push(nw); }
    });
    return {p: withImg(p), score, hits};
  }).filter(r => r.score >= 0).sort((a, b) => b.score - a.score);
}

function matchQuiz(tags, g) {
  return PERFUMES.map(p => {
    if (g !== 'all' && p.gender !== g && p.gender !== '中性') return {p: withImg(p), score: -1, hits: []};
    let s = 0; const hits = [];
    Object.keys(tags).forEach(t => { if (p.tags.includes(t)) { s += tags[t] * 2; hits.push(TAG_CN[t]); } });
    return {p: withImg(p), score: s, hits};
  }).filter(r => r.score >= 0).sort((a, b) => b.score - a.score);
}

return {PERFUMES, TAG_CN, KW, NOTE_WORDS, MOODS, P_MOOD, matchSearch, matchQuiz, withImg};

